    if (st.paused)
      console.log("  Agents stopped from the app: press Start agents under My agents → This computer.");
    for (const a of st.agents)
      console.log(`  ${a.online ? "●" : "○"} ${a.name}  ${a.mode}  ${a.workdir}  ${a.councils.map((c) => "#" + c).join(" ")}${a.running ? "  (answering…)" : ""}`);
